$ip='172.26.169.198'; $cred=New-Object System.Management.Automation.PSCredential('FakeWheel',(ConvertTo-SecureString 'FakeWheel!2026' -AsPlainText -Force)); $s=New-PSSession -ComputerName $ip -Credential $cred -ErrorAction Stop; Invoke-Command -Session $s -ScriptBlock { Get-PnpDevice -Class HIDClass -ErrorAction SilentlyContinue | Select-Object Status,FriendlyName,InstanceId | Format-Table -AutoSize | Out-String; Get-PnpDevice -ErrorAction SilentlyContinue | Where-Object { $_.FriendlyName -match 'Fake|Logitech|HID' } | Select-Object Status,Class,FriendlyName,InstanceId | Format-Table -AutoSize | Out-String }; Remove-PSSession $s